"""Prompt Bible command library (generated by scripts/build_director_commands.py)."""
import json
from functools import lru_cache
from pathlib import Path

DIR = Path(__file__).parent
MOVEMENT_GROUP = "movement"
# Bible §11 conflicts that the per-command "TRÁNH" columns don't spell out by id.
_EXTRA_CONFLICTS = {
    frozenset({"zoom-in", "dolly-in"}), frozenset({"zoom-out", "dolly-out"}),
    frozenset({"pov", "over-shoulder"}), frozenset({"low-angle", "high-angle"}),
    frozenset({"low-angle", "overhead"}), frozenset({"low-angle", "birds-eye"}),
    frozenset({"worms-eye", "overhead"}), frozenset({"handheld", "gimbal"}),
    frozenset({"handheld", "steadicam"}), frozenset({"handheld", "robot-arm"}),
}


@lru_cache(maxsize=1)
def load_commands() -> dict[str, dict]:
    entries = json.loads((DIR / "commands.json").read_text(encoding="utf-8"))
    out: dict[str, dict] = {}
    for e in entries:
        out[e["id"]] = e
        for a in e["aliases"]:
            out[a] = e
    return out


def resolve(cmd: str) -> dict | None:
    return load_commands().get(cmd.strip().lstrip("/").lower())


def group_of(cmd: str) -> str | None:
    e = resolve(cmd)
    return e["group"] if e else None


def type_of(cmd: str) -> str | None:
    e = resolve(cmd)
    return e["type"] if e else None


def conflicts(a: str, b: str) -> bool:
    ea, eb = resolve(a), resolve(b)
    if not ea or not eb or ea is eb:
        return False
    if frozenset({ea["id"], eb["id"]}) in _EXTRA_CONFLICTS:
        return True
    if "static" in (ea["id"], eb["id"]):
        other = eb if ea["id"] == "static" else ea
        return other["group"] == MOVEMENT_GROUP
    return eb["id"] in ea["avoid"] or ea["id"] in eb["avoid"]
